// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue, uniqueSuffix } from '@skyramp/skyramp';
import { createLink, getDashboardList, deleteLinks, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const collectionName = uniqueSuffix("Dashboard Envelope Collection");
    const linkOneUrl = uniqueSuffix("https://dashboard-envelope-one.example.com/a");

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Dashboard Envelope Collection"
        },
        "name": "Dashboard Envelope Link One",
        "tags": [],
        "type": "url",
        "url": "https://dashboard-envelope-one.example.com/a"
    }`;

    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody, {
        "collection.name": collectionName,
        "url": linkOneUrl
    });

    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Dashboard Envelope Link One");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe(linkOneUrl);
    expect(Number(getResponseValue(linksPostResponse, "response.id")), 'id').toBeGreaterThan(0);

    const collectionId = getResponseValue(linksPostResponse, "response.collectionId");
    const linkOneId = getResponseValue(linksPostResponse, "response.id");

    try {
        const dashboardGetResponse = await getDashboardList(client, URL_localhost, headers, {"sort": ["0"]});

        expect(dashboardGetResponse.statusCode, 'status code').toBe(200);

        // The pull request description requires the {data, meta} envelope of both list endpoints:
        // "BREAKING CHANGE: Link[] -> {data: Link[], meta: {total, cursor}}. Both list endpoint affected."
        // GET /api/v1/dashboard is the other endpoint that returned a bare Link[] under "response".
        expect(Array.isArray(getResponseValue(dashboardGetResponse, "response")), 'response is not a bare array').toBe(false);

        const dashboardLinks = getResponseValue(dashboardGetResponse, "response.data");
        expect(Array.isArray(dashboardLinks), 'response.data is an array').toBe(true);
        expect(dashboardLinks.length, 'the dashboard lists the created link').toBeGreaterThan(0);
        expect(getResponseValue(dashboardGetResponse, "response.data.0.id"), 'the created link is listed first').toBe(linkOneId);
        expect(getResponseValue(dashboardGetResponse, "response.data.0.name"), 'the created link name').toBe("Dashboard Envelope Link One");
        expect(getResponseValue(dashboardGetResponse, "response.meta.total"), 'meta.total').toBe(dashboardLinks.length);
        expect(getResponseValue(dashboardGetResponse, "response.meta.cursor"), 'meta.cursor on a partial page').toBeNull();
    } finally {
        // Request Body
        const linksDeleteRequestBody: string = `{
            "linkIds": [
                ${linkOneId}
            ]
        }`;

        const linksDeleteResponse = await deleteLinks(client, URL_localhost, headers, linksDeleteRequestBody);

        expect(linksDeleteResponse.statusCode, 'status code').toBe(200);

        expect(getResponseValue(linksDeleteResponse, "response.count"), 'deleted link count').toBe(1);

        const collectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, collectionId);

        expect(collectionsDeleteResponse.statusCode, 'status code').toBe(200);

        expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'deleted collection id').toBe(collectionId);
        expect(getResponseValue(collectionsDeleteResponse, "response.name"), 'deleted collection name').toBe(collectionName);
    }
});
